export class TransactionsComponent {
  data = inject(DataService);
  auth = inject(AuthService);
  fb = inject(FormBuilder);

  currency = this.data.currencySymbol;

  filterForm = this.fb.group({
    status: ['All'],
    startDate: [''],
    endDate: ['']
  });

  filters = signal({ status: 'All', startDate: '', endDate: '' });

  filteredTransactions = computed(() => {
    const txs = this.data.transactions();
    const f = this.filters();

    return txs.filter(tx => {
      // Status
      if (f.status !== 'All' && tx.status !== f.status) {
        return false;
      }

      const txDate = new Date(tx.date).getTime();

      // Start Date
      if (f.startDate) {
        // Parse input date. Assuming input is YYYY-MM-DD (UTC midnight usually)
        const start = new Date(f.startDate).getTime();
        if (txDate < start) return false;
      }

      // End Date
      if (f.endDate) {
        // We want to include the whole end day.
        const end = new Date(f.endDate);
        // Add 24h (86400000ms) to include the full day
        const endTime = end.getTime() + 86400000; 
        if (txDate >= endTime) return false;
      }

      return true;
    });
  });

  constructor() {
    this.filterForm.valueChanges.subscribe(val => {
      this.filters.set({
        status: val.status || 'All',
        startDate: val.startDate || '',
        endDate: val.endDate || ''
      });
    });
  }

  resetFilters() {
    this.filterForm.reset({
      status: 'All',
      startDate: '',
      endDate: ''
    });
  }

  getProjectName(id: string): string {
    return this.data.projects().find(p => p.id === id)?.name || 'Unknown Project';
  }

  getStatusClass(status: string): string {
    switch (status) {
      case 'Success': return 'bg-emerald-100 text-emerald-800';
      case 'Pending': return 'bg-amber-100 text-amber-800';
      case 'Failed': return 'bg-red-100 text-red-800';
      case 'Cancelled': return 'bg-slate-200 text-slate-700';
      default: return 'bg-slate-100 text-slate-600';
    }
  }
}

import { Injectable, signal, computed } from '@angular/core';
