@Injectable({
  providedIn: 'root'
})
export class DataService {
  // Signals acting as database tables
  gateways = signal<Gateway[]>([]);
  projects = signal<Project[]>([]);
  transactions = signal<Transaction[]>([]);
  users = signal<User[]>([]);

  // Computed Financials
  financials = computed(() => {
    const txs = this.transactions();
    const projs = this.projects();

    return projs.map(p => {
      const projectTxs = txs.filter(t => t.project_id === p.id && t.status === 'Success');
      const totalEarned = projectTxs.reduce((sum, t) => sum + t.amount, 0);

      // Mock released amount storage logic would go here, simpler to just calc on fly for now
      // For this demo, we'll store released amount in a separate simplistic map or just mock it 
      // as 80% of earned to show some data.
      const released = Math.floor(totalEarned * 0.8); 

      return {
        project_id: p.id,
        project_name: p.name,
        total_earned: totalEarned,
        released_amount: released,
        balance: totalEarned - released
      };
    });
  });

  activeGateway = computed(() => this.gateways().find(g => g.active));
  currencySymbol = computed(() => {
    const gw = this.activeGateway();
