    {
      id: uuidv4(),
      amount: 100,
      currency: 'BDT',
      status: 'Success',
      mode: 'Live',
      logs: [
        {timestamp: new Date().toISOString(), message: 'Transaction created', actor: 'System'},
        {timestamp: new Date().toISOString(), message: 'Payment processed', actor: 'System'},
        {timestamp: new Date().toISOString(), message: 'Funds transferred', actor: 'System'}
      ]
    },
    {
      id: uuidv4(),
      amount: 50,
      currency: 'USD',
      status: 'Pending',
      mode: 'Sandbox',
      logs: [
        {timestamp: new Date().toISOString(), message: 'Transaction initiated', actor: 'User123'},
        {timestamp: new Date().toISOString(), message: 'Approval required', actor: 'System'},
      ]
    },
  ];

  constructor() {
    this.transactionsSubject.next(this.seedData);
  }

  addTransaction(transaction: Omit<Transaction, 'id' | 'logs'>, actor: string): void {
    const newTransaction: Transaction = {
      ...transaction,
      id: uuidv4(),
      logs: [
        {timestamp: new Date().toISOString(), message: 'Transaction created', actor: actor},
      ]
    };
    this.seedData.push(newTransaction);
    this.transactionsSubject.next([...this.seedData]);
  }

  updateTransactionStatus(id: string, newStatus: TxStatus, actor: string): void {
    this.seedData = this.seedData.map(tx => {
      if (tx.id === id) {
        tx.status = newStatus;
        tx.logs.push({timestamp: new Date().toISOString(), message: `Status updated to ${newStatus}`, actor: actor});
      }
      return tx;
    });
    this.transactionsSubject.next([...this.seedData]);
  }
}
